    }
  },
  "required": [
    "id"
  ]
}

{
  "type": "object",
  "properties": {
    "id": {
      "type": "string",
      "description": "The background job id to abort."
    }
  },
  "required": [
    "id"
  ]
}

{
  "type": "object",
  "properties": {
